import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const RenderText = ({ value, svgUrl, bold, italic, stroke, strokeColor, className = '', style = {}, tag: Tag = 'span' }) => {
    if (svgUrl) {
        return <img src={svgUrl} alt={value} className={`block object-contain ${className}`} style={style} />;
    }
    const computedStyle = {
        ...style,
        fontWeight: bold ? 'bold' : undefined,
        fontStyle: italic ? 'italic' : undefined,
        WebkitTextStroke: stroke ? `1px ${strokeColor || '#ffffff'}` : undefined,
    };
    return <Tag className={className} style={computedStyle}>{value}</Tag>;
};

const AdMiddle = ({ page = 'home' }) => {
    const [middleAds, setMiddleAds] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAds = async () => {
            try {
                const { data } = await axios.get(`http://localhost:5001/api/advertisements?bannerType=middle&page=${page}`);
                setMiddleAds(data);
                setLoading(false);
            } catch (error) {
                console.error("Error fetching middle ads:", error);
                setLoading(false);
            }
        };
        fetchAds();
    }, [page]);

    if (loading || middleAds.length === 0) return null;

    const ad = middleAds[0];

    return (
        <section className="relative w-full h-[300px] lg:h-[400px] overflow-hidden my-12">
            {/* Background Image */}
            <img
                src={ad.mediaUrl}
                alt={ad.title}
                className="w-full h-full object-cover"
            />

            {/* Overlay Content */}
            <div className="absolute inset-0 bg-black/20 flex items-center px-12 lg:px-24">
                <div className="max-w-xl text-white">
                    {ad.tag && (
                        <RenderText
                            tag="p"
                            value={ad.tag}
                            svgUrl={ad.tagSvgUrl}
                            bold={ad.tagBold}
                            italic={ad.tagItalic}
                            stroke={ad.tagStroke}
                            strokeColor={ad.tagStrokeColor}
                            className="text-xs lg:text-sm font-medium tracking-widest uppercase mb-2 opacity-90"
                            style={{ color: ad.tagColor || '#ffffff' }}
                        />
                    )}

                    <RenderText
                        tag="h2"
                        value={ad.title}
                        svgUrl={ad.titleSvgUrl}
                        bold={ad.titleBold}
                        italic={ad.titleItalic}
                        stroke={ad.titleStroke}
                        strokeColor={ad.titleStrokeColor}
                        className="text-4xl lg:text-6xl font-serif font-bold uppercase leading-tight mb-2 tracking-tighter"
                        style={{ color: ad.titleColor || '#ffffff' }}
                    />

                    {ad.subtitle && (
                        <RenderText
                            tag="p"
                            value={ad.subtitle}
                            svgUrl={ad.subtitleSvgUrl}
                            bold={ad.subtitleBold}
                            italic={ad.subtitleItalic}
                            stroke={ad.subtitleStroke}
                            strokeColor={ad.subtitleStrokeColor}
                            className="text-sm lg:text-lg font-medium tracking-wider uppercase mb-8 opacity-80"
                            style={{ color: ad.subtitleColor || '#ffffff' }}
                        />
                    )}

                    {ad.ctaText && (
                        <Link
                            to={ad.ctaLink || '/shop'}
                            className="inline-block border border-white px-8 py-3 bg-black/10 backdrop-blur-sm text-sm font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-all"
                            style={{ color: ad.ctaColor || '#ffffff', borderColor: ad.ctaColor || '#ffffff' }}
                        >
                            {ad.ctaText}
                        </Link>
                    )}
                </div>
            </div>
        </section>
    );
};

export default AdMiddle;
